+              retry({
+                count: MAX_RETRIES,
+                delay: () => timer(RETRY_DELAY_MS, scheduler),
+              }),
+              catchError(() => EMPTY),
+            );
+          }),
+        );
+      }),
+    )
+    .subscribe();
+
+  return {
+    stop: () => subscription.unsubscribe(),
+  };
